# Writes the hedra command files of the dawn marsh: pond.txt (water with the sun's broken reflection
# and sky-coloured sheen dashes), bank.txt (the far bank and the two side banks), reeds.txt, pad.txt,
# lotus.txt, stone.txt, log.txt, sun.txt, cloud.txt, mist.txt, ripple.txt.
# Run from models/env: /usr/bin/python3 make_env.py
# Up Z, front -Y (hedra); colours exact Eggy 15. World (glTF) = (x, z, -y) of hedra.
import math, random

HEX = {"black": "0e0c1b", "moss": "2e403d", "slate": "495266", "indigo": "4609a1", "cream": "f0f2d0",
       "red": "ca1e0f", "teal": "3c9b87", "magenta": "c41be3", "mauve": "9e7e74", "pink": "f63468",
       "cyan": "2bcff2", "orange": "ea9d18", "lime": "afd87e", "bone": "ddd4cb", "yellow": "f9d955"}
def col(n):
    h = HEX[n]
    return "--base-color " + " ".join(f"{int(h[i:i + 2], 16) / 255:.4f}" for i in (0, 2, 4))

SUN_X = -2.6        # the sun's world x: its reflection runs down the water under it
files = {}

# ---------------------------------------------------------------- pond
rnd = random.Random(11)
glint, glint_o, sheen = [], [], []
def box(x0, x1, y0, y1):
    return f"(pos.x > {x0:.3f} && pos.x < {x1:.3f} && pos.y > {y0:.3f} && pos.y < {y1:.3f})"
z = -4.6
while z < 5.5:                                   # world z (towards the camera); hedra y = -z
    h = 0.25
    t = (z + 4.6) / 10.1                         # 0 at the far bank, 1 near the camera
    if rnd.random() < 0.85 - 0.45 * t:
        w = (1.5 - 1.1 * t) * rnd.uniform(0.6, 1.0)
        c = SUN_X + rnd.uniform(-0.3, 0.3) * (1 + t)
        glint.append(box(c - w * 0.32, c + w * 0.32, -z - h, -z))
        glint_o.append(box(c - w * 0.5, c + w * 0.5, -z - h, -z))
    z += h * (1 if t < 0.4 else 2)
for i in range(30):
    zz = rnd.uniform(-4.4, 9.0); xx = rnd.uniform(-6.5, 6.5)
    if abs(xx - SUN_X) < 1.2:
        continue
    w = rnd.uniform(0.5, 1.6) * (1.0 if zz < 2 else 1.5)
    sheen.append(box(xx - w / 2, xx + w / 2, -zz - 0.25, -zz))
files["pond"] = f"""# Pond: the water, a 14 x 16 m grid (world z -5 to 11, x -7 to 7) at y 0, cells 0.25 m. Faces in
# a broken column under the sun are its reflection (Glint yellow in the middle, GlintEdge orange
# round it); scattered dashes (Sheen) catch the sky's magenta. Generated by make_env.py.
new
material new Water {col('indigo')} --no-slot
material new Sheen {col('magenta')} --no-slot
material new Glint {col('yellow')} --no-slot
material new GlintEdge {col('orange')} --no-slot
add mesh grid --name Pond --size 1 --x-subdivisions 56 --y-subdivisions 64 --location 0 0 0
scale 14 16 1
apply --scale
set location 0 -3 0
apply --location
material assign Water
mode edit
select face where "{' || '.join(sheen)}"
material assign Sheen
select face where "{' || '.join(glint_o)}"
material assign GlintEdge
select face where "{' || '.join(glint)}"
material assign Glint
mode object
shade flat
export pond.glb
"""

# ---------------------------------------------------------------- banks
files["bank"] = f"""# Banks: the far bank (a long low ridge across the back, mossy top, slate mud face towards the
# pond) and two side banks (flattened lumps at the left and right edges). Built in place (world
# x, -z). Generated by make_env.py.
new
material new Moss {col('moss')} --no-slot
material new Mud {col('slate')} --no-slot
add mesh cube --name Far --size 1 --location 0 4.95 0.0
scale 16 1.5 0.6
apply --scale
mode edit
select face where "normal.z < -0.9"
delete only-faces
select face where "normal.z > 0.9"
subdivide --cuts 12
select vert where "pos.z > 0.25"
randomize --amount 0.08 --seed 4
mode object
add mesh ico-sphere --name Left --subdivisions 2 --radius 1 --location -6.3 1.2 -0.25
scale 1.9 3.6 0.75
apply --scale
add mesh ico-sphere --name Right --subdivisions 2 --radius 1 --location 6.4 1.8 -0.3
scale 1.8 3.4 0.8
apply --scale
select Far Left Right
active Far
join
rename Far Bank
material assign Mud
mode edit
select face where "normal.z > 0.55"
material assign Moss
select vert where "pos.z < -0.35"
delete vert
mode object
shade flat
export bank.glb
"""

# ---------------------------------------------------------------- reeds
rnd = random.Random(5)
blades, names = [], []
for i in range(9):
    a = rnd.uniform(0, 2 * math.pi); d = rnd.uniform(0.0, 0.32)
    x, y = d * math.cos(a), d * math.sin(a)
    h = rnd.uniform(0.8, 1.55)
    tx, ty = rnd.uniform(-9, 9), rnd.uniform(-9, 9)
    blades += [f"add mesh cube --name Bl{i} --size 1 --location {x:.3f} {y:.3f} {h / 2:.3f}",
               f"scale 0.09 0.06 {h:.3f}", "apply --scale", "mode edit",
               f"select vert where \"pos.z > {h * 0.45:.3f}\"", "scale 0.35 0.6 1", "mode object",
               f"set rotation {tx:.1f} {ty:.1f} {rnd.uniform(0, 180):.0f}", "apply --rotation"]
    names.append(f"Bl{i}")
heads, hn = [], []
for i in range(3):
    a = 2 * math.pi * i / 3 + 0.4; d = 0.18
    x, y = d * math.cos(a), d * math.sin(a); h = 1.15 + 0.2 * i
    heads += [f"add mesh cylinder --name St{i} --vertices 5 --radius 0.035 --depth {h:.2f} --location {x:.3f} {y:.3f} {h / 2:.3f}",
              f"add mesh cylinder --name Hd{i} --vertices 6 --radius 0.075 --depth 0.3 --location {x:.3f} {y:.3f} {h - 0.05:.3f}"]
    names.append(f"St{i}"); hn.append(f"Hd{i}")
files["reeds"] = f"""# Reeds: a clump of nine tapered blades (0.8 to 1.55 m, leaning a little) and three cattails (a
# brown head on a stalk). Origin on the ground at the clump's centre. Generated by make_env.py.
new
material new Reed {col('moss')} --no-slot
material new Cattail {col('mauve')} --no-slot
""" + "\n".join(blades + heads) + f"""
select {' '.join(names)}
active Bl0
join
rename Bl0 Reeds
material assign Reed
select {' '.join(hn)}
active Hd0
join
rename Hd0 Heads
material assign Cattail
select all
shade flat
export reeds.glb
"""

# ---------------------------------------------------------------- lily pad, lotus
files["pad"] = f"""# Lily pad: a 14-sided disc 1.24 m across, 0.06 thick, with its notch (one rim vertex pulled to
# the middle). Origin at the water line. Generated by make_env.py.
new
material new Pad {col('teal')} --no-slot
add mesh cylinder --name Pad --vertices 14 --radius 0.62 --depth 0.06 --location 0 0 0.03
material assign Pad
mode edit
select vert where "pos.x > 0.6"
translate -0.52 0 0
select face where "normal.z < -0.9"
delete only-faces
mode object
shade flat
export pad.glb
"""
pet, pn = [], []
for ring, (n, r, tilt, z0) in enumerate(((6, 0.17, 35, 0.12), (5, 0.08, 15, 0.2))):
    for i in range(n):
        a = 2 * math.pi * (i + 0.5 * ring) / n
        pet += [f"add mesh cone --name P{ring}{i} --vertices 4 --radius1 0.09 --radius2 0 --depth 0.3 --location 0 0 0",
                "scale 1 0.55 1", "apply --scale",
                f"set rotation {tilt} 0 {math.degrees(a) + 90:.1f}", "apply --rotation",
                f"set location {r * math.cos(a):.3f} {r * math.sin(a):.3f} {z0}", "apply --location"]
        pn.append(f"P{ring}{i}")
files["lotus"] = f"""# Lotus: a pad with a pink flower, two rings of pointed petals round a yellow centre.
# Origin at the water line. Generated by make_env.py.
new
material new Pad {col('teal')} --no-slot
material new Petal {col('pink')} --no-slot
material new Heart {col('yellow')} --no-slot
add mesh cylinder --name Pad --vertices 12 --radius 0.5 --depth 0.06 --location 0 0 0.03
material assign Pad
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
""" + "\n".join(pet) + f"""
select {' '.join(pn)}
active P00
join
rename P00 Petals
material assign Petal
add mesh cylinder --name Heart --vertices 6 --radius 0.08 --depth 0.12 --location 0 0 0.2
material assign Heart
select all
shade flat
export lotus.glb
"""

# ---------------------------------------------------------------- stone, log
files["stone"] = f"""# Stone: the lead singer's seat, a 9-sided boulder 1.3 m across, its mossy top 0.33 m above the
# water. Origin at the water line. Generated by make_env.py.
new
material new Rock {col('slate')} --no-slot
material new Moss {col('moss')} --no-slot
add mesh cylinder --name Stone --vertices 9 --radius 0.66 --depth 0.55 --location 0 0 0.06
apply --location
material assign Rock
mode edit
select face where "normal.z < -0.9"
delete only-faces
select vert where "pos.z > 0.3"
scale 0.82 0.82 1
select face where "normal.z > 0.9"
material assign Moss
select vert where "pos.z > -0.1"
randomize --amount 0.05 --seed 9
mode object
shade flat
export stone.glb
"""
files["log"] = f"""# Log: a fallen trunk 3.2 m long, 0.56 thick (the scene sinks it 0.12 m into the water); pale cut
# ends; the faces looking down are deleted. Origin on its axis. Generated by make_env.py.
new
material new Bark {col('mauve')} --no-slot
material new Cut {col('bone')} --no-slot
add mesh cylinder --name Log --vertices 8 --radius 0.28 --depth 3.2 --location 0 0 0 --rotation 0 90 0
apply --rotation
material assign Bark
mode edit
select face where "abs(normal.x) > 0.9"
material assign Cut
select face where "normal.z < -0.3"
delete only-faces
mode object
shade flat
export log.glb
"""

# ---------------------------------------------------------------- sky pieces
files["sun"] = f"""# Sun: a 16-sided disc 3 m across facing the camera (only its front face), rising behind the far
# bank. Origin at its centre. Generated by make_env.py.
new
material new Sun {col('yellow')} --no-slot
add mesh cylinder --name Sun --vertices 16 --radius 1.5 --depth 0.1 --location 0 0 0 --rotation 90 0 0
apply --rotation
material assign Sun
mode edit
select face where "normal.y > -0.9"
delete only-faces
mode object
shade flat
export sun.glb
"""
cl = []
for i, (x, z, w) in enumerate(((-2.2, 0.2, 3.6), (-3.4, -0.25, 2.0), (2.4, 0.15, 3.0), (3.9, -0.2, 1.6))):
    cl += [f"add mesh cube --name C{i} --size 1 --location {x} 0 {z}", f"scale {w} 0.05 0.13", "apply --scale"]
files["cloud"] = f"""# Cloud strips: four thin flat bars across the dawn sky (two over the sun). Facing the camera.
# Generated by make_env.py.
new
material new Cloud {col('bone')} --no-slot
""" + "\n".join(cl) + """
select C0 C1 C2 C3
active C0
join
rename C0 Clouds
material assign Cloud
shade flat
export cloud.glb
"""
files["mist"] = f"""# Mist: one low flat wisp 2.6 x 0.9 x 0.26 m (a game bone pool drifts them along the far bank).
# Origin at its centre. Generated by make_env.py.
new
material new Mist {col('bone')} --no-slot
add mesh ico-sphere --name Mist --subdivisions 1 --radius 0.5 --location 0 0 0
scale 2.6 0.9 0.26
apply --scale
material assign Mist
mode edit
select all
randomize --amount 0.04 --seed 3
mode object
shade flat
export mist.glb
"""
files["ripple"] = f"""# Ripple: a flat ring 2.4 m across (baked at its largest; the game scales it up from small).
# Origin at its centre on the water. Generated by make_env.py.
new
material new Ripple {col('bone')} --no-slot
add mesh torus --name Ripple --major-segments 32 --minor-segments 4 --major-radius 1.2 --minor-radius 0.045 --location 0 0 0
scale 1 1 0.4
apply --scale
material assign Ripple
shade flat
export ripple.glb
"""

for k, v in files.items():
    open(f"{k}.txt", "w").write(v)
print("wrote", ", ".join(f"{k}.txt" for k in files))
